ComfyXP=ComfyXP or {}
local A=ComfyXP
function A:CreateXPBar() if self.xpFrame then return end local f=CreateFrame("StatusBar","ComfyXPBar",UIParent,"BackdropTemplate"); f:SetStatusBarTexture("Interface\\TargetingFrame\\UI-StatusBar"); f:SetBackdrop({bgFile="Interface\\Buttons\\WHITE8X8",edgeFile="Interface\\Tooltips\\UI-Tooltip-Border",edgeSize=10}); f:SetBackdropColor(.02,.02,.03,.82); f:SetStatusBarColor(.15,.45,.95,.95); f:SetMovable(true); f:EnableMouse(true); f:RegisterForDrag("LeftButton"); f.text=f:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall"); f.text:SetPoint("CENTER"); f.sub=f:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall"); f.sub:SetPoint("TOP",f,"BOTTOM",0,-2); f:SetScript("OnDragStart",function(self) if not A.db.xp.locked then self:StartMoving() end end); f:SetScript("OnDragStop",function(self) self:StopMovingOrSizing(); local p,_,rp,x,y=self:GetPoint(1); A.db.xp.point=p; A.db.xp.relativePoint=rp or p; A.db.xp.x=x or 0; A.db.xp.y=y or 0 end); self.xpFrame=f end
function A:RefreshFeature() self:CreateXPBar(); local f=self.xpFrame; local c=self.db and self.db.xp; if not c or not self.db.enabled then f:Hide(); return end; local level=UnitLevel and tonumber(UnitLevel("player")) or 0; local xp=UnitXP and tonumber(UnitXP("player")) or 0; local max=UnitXPMax and tonumber(UnitXPMax("player")) or 1; if not max or max<=0 then max=1 end; local rested=GetXPExhaustion and tonumber(GetXPExhaustion()) or 0; f:ClearAllPoints(); f:SetPoint(c.point or "BOTTOM",UIParent,c.relativePoint or c.point or "BOTTOM",c.x or 0,c.y or 52); f:SetSize(tonumber(c.width) or 520,tonumber(c.height) or 18); f:SetMinMaxValues(0,max); f:SetValue(xp); f.text:SetText(string.format("Lv %d  %d / %d  (%.1f%%)",level or 0,xp or 0,max,(xp/max)*100)); local sub={}; if c.showRested and rested and rested>0 then sub[#sub+1]=A:T("RESTED")..": "..rested end; local ph=A.activeSeconds and A.activeSeconds>5 and ((A.sessionXP or 0)/A.activeSeconds)*3600 or 0; if c.showSubline then sub[#sub+1]=A:T("SESSION")..": "..tostring(A.sessionXP or 0); if ph>0 then sub[#sub+1]=A:T("PER_HOUR")..": "..math.floor(ph+.5); sub[#sub+1]=A:T("ETA")..": "..string.format("%.1f h",math.max(0,max-xp)/ph) end end; f.sub:SetText(table.concat(sub,"  |  ")); f:Show() end
function A:OnXPUpdate() local xp=UnitXP and tonumber(UnitXP("player")) or 0; local max=UnitXPMax and tonumber(UnitXPMax("player")) or 1; if self.lastXP and self.lastXPMax then local d=xp-self.lastXP; if d<0 then d=(self.lastXPMax-self.lastXP)+xp end; if d>0 then self.sessionXP=(self.sessionXP or 0)+d end end; self.lastXP=xp; self.lastXPMax=max; self:RefreshFeature() end
function A:InitializeFeature() self.sessionXP=0; self.activeSeconds=0; self.lastXP=UnitXP and tonumber(UnitXP("player")) or 0; self.lastXPMax=UnitXPMax and tonumber(UnitXPMax("player")) or 1; self:CreateXPBar(); local e=CreateFrame("Frame"); for _,ev in ipairs({"PLAYER_XP_UPDATE","PLAYER_LEVEL_UP","UPDATE_EXHAUSTION","PLAYER_ENTERING_WORLD"}) do pcall(e.RegisterEvent,e,ev) end; e:SetScript("OnEvent",function(_,ev) if ev=="PLAYER_XP_UPDATE" or ev=="PLAYER_LEVEL_UP" then A:OnXPUpdate() else A:RefreshFeature() end end); e:SetScript("OnUpdate",function(self,dt) self.t=(self.t or 0)+(tonumber(dt) or 0); if self.t>=1 then local step=self.t; self.t=0; local afk=type(UnitIsAFK)=="function" and UnitIsAFK("player"); if not afk then A.activeSeconds=(A.activeSeconds or 0)+step end; A:RefreshFeature() end end) end
function A:BuildGeneralOptions(page,ui) ui.CreateCheck(page,A:T("LOCK_BAR"),20,-95,function() return A.db.xp.locked end,function(v) A.db.xp.locked=v end); ui.CreateCheck(page,A:T("SHOW_RESTED"),20,-130,function() return A.db.xp.showRested end,function(v) A.db.xp.showRested=v end); ui.CreateCheck(page,A:T("SHOW_SUBLINE"),20,-165,function() return A.db.xp.showSubline end,function(v) A.db.xp.showSubline=v end); ui.CreateSlider(page,A:T("WIDTH"),280,800,10,35,-235,function() return A.db.xp.width end,function(v) A.db.xp.width=math.floor(v+0.5) end,function(v) return math.floor(v+0.5).." px" end); ui.CreateSlider(page,A:T("HEIGHT"),10,32,1,35,-305,function() return A.db.xp.height end,function(v) A.db.xp.height=math.floor(v+0.5) end,function(v) return math.floor(v+0.5).." px" end); local n=page:CreateFontString(nil,"ARTWORK","GameFontHighlightSmall"); n:SetPoint("TOPLEFT",20,-395); n:SetWidth(680); n:SetJustifyH("LEFT"); n:SetText(A:T("FOREVER_NOTE")) end
